import assert from "node:assert/strict";
import {readFileSync} from "node:fs";
import {HOLY_CLOAK_SOURCE_ACCESS_V1 as w,holyCloakSourceMatches} from "../src/pray/holy-cloak-source-access.v1.js";
assert.equal(w.id,"st_joseph_holy_cloak_30_days");
assert.equal(w.subject,"VI");
assert.deepEqual(w.schedule,{dayCount:30,sameCompleteDailyForm:true,distinctDailyPrayers:0});
assert.equal(w.primary.language,"en");
assert.equal(w.primary.form,"FIVE_SECTION_ENGLISH_PRESENTATION");
