assert.equal(w.otherWitnesses[0].form,"SIX_SECTION_ENGLISH_PRESENTATION_WITH_ADDITIONAL_CLOSING_PRAYER");
assert.equal(w.otherWitnesses[1].form,"CLAIMED_1882_ITALIAN_NINETEEN_NUMBERED_PASSAGES_WITH_IMAGE_ONLY_TEXT");
