assert.equal(holyCloakSourceMatches({search:"holy cloak",subject:"VI",category:"essentials"}),false);
assert.equal(holyCloakSourceMatches({search:"not a matching prayer",subject:"VI"}),false);
const ui=readFileSync(new URL("../src/pray/presentation-runtime.js",import.meta.url),"utf8");
assert.match(ui,/holyCloakSourceMatches\(\{search:q,subject:LIB\.subject,category:LIB\.cat\}\)/);
assert.match(ui,/data-ao-holy-cloak-source-only/);
assert.match(ui,/data-ao-holy-cloak-source-link/);
assert.match(ui,/data-ao-holy-cloak-italian-open/);
assert.match(ui,/data-ao-holy-cloak-italian-reader/);
assert.match(ui,/data-ao-holy-cloak-italian-limits/);
assert.match(ui,/data-p435930-hc-prev/);
assert.match(ui,/data-p435930-hc-next/);
assert.match(ui,/data-p435930-hc-finish/);
assert.match(ui,/rel="noopener noreferrer"/);
assert.match(ui,/No certified EN\/FR body translation/);
assert.match(ui,/collation de l’original en attente/);
assert.match(ui,/\$\{massSequenceSection\}\$\{holyCloakSection\}\$\{guidedSection\}/);
const sourceModule=readFileSync(new URL("../src/pray/holy-cloak-source-access.v1.js",import.meta.url),"utf8");
assert.doesNotMatch(sourceModule,/Offering I:|Prayer I: Hail|Holy Mary, pray for us/,"No copied modern prayer bodies in source-access module");
assert.doesNotMatch(ui,/data-ao-holy-cloak-source-link[^;]*data-p435930-lib-open/,"External source must not claim native canonical card");
console.log("Holy Cloak: complete native IT 19-section source owned; historical 1909 litany; external EN parish witness source link; 30 same-form days; historical print/EN-FR holds PASS");
